const TINT = {"bash": "#7fb4ee", "guard": "#7fb4ee", "charge": "#e8c46a", "boulder": "#c7a47c", "spin": "#f0c26a", "inferno": "#ff8a3c", "rage": "#ef5a3c", "meteor": "#ff7a2e", "spirit": "#f2c14e"};

// def: CONFIG'teki yetenek tanımı ({ id, icon }). İkonu yoksa eski emoji gösterilir.
export function skillIcon(def) {
  const d = P[def.id];
  return d ? `<svg class="sk-ico" viewBox="0 0 512 512" aria-hidden="true"><path fill="currentColor" d="${d}"/></svg>` : `<span>${def.icon || ''}</span>`;
}
export const skillTint = (def) => TINT[def.id] || '#d9a441';

// Ekipman ikonu: adı game-icons dosya adıdır (CONFIG.gear içindeki tier.icon)
export function gearIcon(name) {
  const d = P[name];
  return d ? `<svg class="sk-ico" viewBox="0 0 512 512" aria-hidden="true"><path fill="currentColor" d="${d}"/></svg>` : '';
}
